def get_connected_components (grid ):
    """
    Identifies all distinct connected components in a 2D grid.
    Each component is returned as a list of (row, col) coordinates.
    """
    rows =len (grid )
    cols =len (grid [0 ])
    visited =set ()
    components =[]

    for r in range (rows ):
        for c in range (cols ):
            if grid [r ][c ]!=0 and (r ,c )not in visited :
                component =[]
                stack =[(r ,c )]
                visited .add ((r ,c ))
                while stack :
                    curr_r ,curr_c =stack .pop ()
                    component .append ((curr_r ,curr_c ))
                    # Check 4-connectivity (up, down, left, right)
                    for dr ,dc in [(0 ,1 ),(0 ,-1 ),(1 ,0 ),(-1 ,0 )]:
                        nr ,nc =curr_r +dr ,curr_c +dc 
                        if 0 <=nr <rows and 0 <=nc <cols and grid [nr ][nc ]!=0 and (nr ,nc )not in visited :
                            visited .add ((nr ,nc ))
                            stack .append ((nr ,nc ))
                components .append (component )
    return components

