    rows =len (grid )
    cols =len (grid [0 ])

    # Identify all non-zero connected components
    visited =set ()
    components =[]
    for r in range (rows ):
        for c in range (cols ):
            if grid [r ][c ]!=0 and (r ,c )not in visited :
                component =[]
                stack =[(r ,c )]
                visited .add ((r ,c ))
                while stack :
                    curr_r ,curr_c =stack .pop ()
                    component .append ((curr_r ,curr_c ))
                    for dr ,dc in [(0 ,1 ),(0 ,-1 ),(1 ,0 ),(-1 ,0 )]:
                        nr ,nc =curr_r +dr ,curr_c +dc 
                        if 0 <=nr <rows and 0 <=nc <cols and grid [nr ][nc ]!=0 and (nr ,nc )not in visited :
                            visited .add ((nr ,nc ))
                            stack .append ((nr ,nc ))
                components .append (component )

                # Determine the target color
                # Rule: If multiple distinct non-zero colors exist, use 5, else use 4.
    unique_colors =set ()
    for r in range (rows ):
        for c in range (cols ):
            if grid [r ][c ]!=0 :
                unique_colors .add (grid [r ][c ])

    target_color =5 if len (unique_colors )>1 else 4 

    # Create the output grid
    output =[[0 for _ in range (cols )]for _ in range (rows )]
    for component in components :
        for r ,c in component :
            output [r ][c ]=target_color 

    return output
